using NexaStation.Core;
using NexaStation.Domain;
using NexaStation.Providers.WindowsApps.Icons;
using Xunit;

namespace NexaStation.Providers.WindowsApps.Tests;

public sealed class Phase77ApplicationVisualTests:IDisposable
{
    private readonly string _root=Path.Combine(Path.GetTempPath(),"NexaStation-IconTests-"+Guid.NewGuid().ToString("N"));
    [Theory]
    [InlineData("Microsoft Store","MS")]
    [InlineData("Windows Media Player","WM")]
    [InlineData("NexaStation","NS")]
    [InlineData("VLC","VL")]
    public async Task InitialFallbackUsesOneOrTwoUsefulLetters(string title,string initials){ApplicationVisualResult result=await new ApplicationVisualResolver(new NullExtractor()).ResolveAsync(new("id",title));Assert.True(result.IsFallback);Assert.Equal(initials,result.FallbackInitials);}

    [Fact] public async Task UserIconHasHighestPriority(){string icon=CreatePng(32,true);RecordingExtractor extractor=new(icon);ApplicationVisualResult result=await new ApplicationVisualResolver(extractor).ResolveAsync(new("id","App",UserSelectedIconPath:icon,PackagedIconPath:icon,ExecutablePath:Environment.ProcessPath));Assert.Equal(ApplicationIconSourceType.UserSelected,result.IconSourceType);Assert.Single(extractor.Requests);}
    [Fact] public async Task PackagedIconPrecedesExecutable(){string icon=CreatePng(64,true);RecordingExtractor extractor=new(icon);ApplicationVisualResult result=await new ApplicationVisualResolver(extractor).ResolveAsync(new("id","App",PackagedIconPath:icon,ExecutablePath:Environment.ProcessPath));Assert.Equal(ApplicationIconSourceType.PackagedApplication,result.IconSourceType);}
    [Fact] public async Task CatalogueIconSupportsWebApplications(){string icon=CreatePng(64,true);RecordingExtractor extractor=new(icon);ApplicationVisualResult result=await new ApplicationVisualResolver(extractor).ResolveAsync(new("id","Web",CatalogueIconPath:icon));Assert.Equal(ApplicationIconSourceType.DiscoverCatalogue,result.IconSourceType);}
    [Theory][InlineData("Streaming")][InlineData("Music")] public async Task CatalogueIconPrecedesExecutableForCuratedMediaServices(string category){string icon=CreatePng(64,true);RecordingExtractor extractor=new(icon);ApplicationVisualResult result=await new ApplicationVisualResolver(extractor).ResolveAsync(new("id","Netflix",CatalogueIconPath:icon,ExecutablePath:Environment.ProcessPath,Category:category));Assert.Equal(ApplicationIconSourceType.DiscoverCatalogue,result.IconSourceType);Assert.Equal("id|DiscoverCatalogue",extractor.Requests.Single().Identity);}
    [Fact] public async Task UserIconStillPrecedesCatalogueForCuratedMediaServices(){string icon=CreatePng(64,true);RecordingExtractor extractor=new(icon);ApplicationVisualResult result=await new ApplicationVisualResolver(extractor).ResolveAsync(new("id","Netflix",UserSelectedIconPath:icon,CatalogueIconPath:icon,ExecutablePath:Environment.ProcessPath,Category:"Streaming"));Assert.Equal(ApplicationIconSourceType.UserSelected,result.IconSourceType);}
    [Fact] public async Task TransparentIconMetadataIsPreserved(){string icon=CreatePng(64,true);ApplicationVisualResult result=await new ApplicationVisualResolver(new RecordingExtractor(icon)).ResolveAsync(new("id","Transparent",PackagedIconPath:icon));Assert.True(result.HasTransparency);}
    [Fact] public async Task HighContrastUsesNeutralSurface(){string icon=CreatePng(64,true);ApplicationVisualResult result=await new ApplicationVisualResolver(new RecordingExtractor(icon)).ResolveAsync(new("id","Contrast",PackagedIconPath:icon,HighContrast:true));Assert.Equal("#FF202020",result.SuggestedBackgroundColor);Assert.Equal("#FFFFFFFF",result.SuggestedForegroundColor);}
    [Fact] public async Task FailureContainsReason(){ApplicationVisualResult result=await new ApplicationVisualResolver(new NullExtractor()).ResolveAsync(new("id","Missing",ExecutablePath:Environment.ProcessPath));Assert.True(result.IsFallback);Assert.NotNull(result.FailureReason);}

    [Fact] public async Task RasterExtractionNormalizesLargeIcon(){string source=CreatePng(16,true);ExtractedApplicationIcon? result=await new ApplicationIconExtractor(_root).ExtractAsync(new("raster",IconLocation:source,DesiredSize:256));Assert.NotNull(result);Assert.Equal(256,result!.Width);Assert.Equal(256,result.Height);}
    [Fact] public async Task ShortcutIconLocationIsSupported(){string source=CreatePng(32,true),shortcut=Path.Combine(_root,"sample.lnk");File.WriteAllText(shortcut,"fixture");ExtractedApplicationIcon? result=await new ApplicationIconExtractor(_root).ExtractAsync(new("shortcut",ShortcutPath:shortcut,IconLocation:source));Assert.NotNull(result);}
    [Fact] public async Task CacheIsReused(){string source=CreatePng(32,true);ApplicationIconExtractor extractor=new(_root);ApplicationIconRequest request=new("cache",IconLocation:source);ExtractedApplicationIcon? first=await extractor.ExtractAsync(request);DateTime write=File.GetLastWriteTimeUtc(first!.CachePath);ExtractedApplicationIcon? second=await extractor.ExtractAsync(request);Assert.Equal(first.CachePath,second!.CachePath);Assert.Equal(write,File.GetLastWriteTimeUtc(second.CachePath));}
    [Fact] public async Task SourceUpdateInvalidatesCache(){string source=CreatePng(32,true);ApplicationIconExtractor extractor=new(_root);ExtractedApplicationIcon? first=await extractor.ExtractAsync(new("updated",IconLocation:source));File.SetLastWriteTimeUtc(source,DateTime.UtcNow.AddMinutes(1));ExtractedApplicationIcon? second=await extractor.ExtractAsync(new("updated",IconLocation:source));Assert.NotEqual(first!.CachePath,second!.CachePath);}
    [Fact] public async Task ConcurrentExtractionDeduplicatesOutput(){string source=CreatePng(32,true);ApplicationIconExtractor extractor=new(_root);Task<ExtractedApplicationIcon?>[] work=Enumerable.Range(0,12).Select(_=>extractor.ExtractAsync(new("parallel",IconLocation:source))).ToArray();ExtractedApplicationIcon?[] results=await Task.WhenAll(work);Assert.Single(results.Select(result=>result!.CachePath).Distinct());}
    [Fact] public async Task CorruptCacheIsRepaired(){string source=CreatePng(32,true);ApplicationIconExtractor extractor=new(_root);ApplicationIconRequest request=new("corrupt",IconLocation:source);ExtractedApplicationIcon? first=await extractor.ExtractAsync(request);await File.WriteAllTextAsync(first!.CachePath,"bad");ExtractedApplicationIcon? repaired=await extractor.ExtractAsync(request);Assert.NotNull(repaired);Assert.True(new FileInfo(repaired!.CachePath).Length>3);}
    [Theory][InlineData(48,64)][InlineData(120,128)][InlineData(512,256)] public async Task StoresOnlyNecessarySizeBuckets(int requested,int expected){string source=CreatePng(16,true);ExtractedApplicationIcon? result=await new ApplicationIconExtractor(_root).ExtractAsync(new($"size-{requested}",IconLocation:source,DesiredSize:requested));Assert.Equal(expected,result!.Width);}
    [Fact] public async Task ExecutableIconExtractionUsesWindowsResource(){ExtractedApplicationIcon? result=await new ApplicationIconExtractor(_root).ExtractAsync(new("exe",ExecutablePath:Environment.ProcessPath,DesiredSize:256));Assert.NotNull(result);Assert.True(result!.Width>0);}

    private string CreatePng(int size,bool transparent){Directory.CreateDirectory(_root);string path=Path.Combine(_root,Guid.NewGuid().ToString("N")+".png");using System.Drawing.Bitmap bitmap=new(size,size,System.Drawing.Imaging.PixelFormat.Format32bppArgb);using System.Drawing.Graphics graphics=System.Drawing.Graphics.FromImage(bitmap);graphics.Clear(transparent?System.Drawing.Color.Transparent:System.Drawing.Color.Navy);using System.Drawing.SolidBrush brush=new(System.Drawing.Color.FromArgb(255,50,110,170));graphics.FillEllipse(brush,2,2,size-4,size-4);bitmap.Save(path,System.Drawing.Imaging.ImageFormat.Png);return path;}
    public void Dispose(){try{Directory.Delete(_root,true);}catch(IOException){}catch(UnauthorizedAccessException){}}
    private sealed class NullExtractor:IApplicationIconExtractor{public Task<ExtractedApplicationIcon?> ExtractAsync(ApplicationIconRequest request,CancellationToken cancellationToken=default)=>Task.FromResult<ExtractedApplicationIcon?>(null);}
    private sealed class RecordingExtractor(string path):IApplicationIconExtractor{public List<ApplicationIconRequest> Requests{get;}=[];public Task<ExtractedApplicationIcon?> ExtractAsync(ApplicationIconRequest request,CancellationToken cancellationToken=default){Requests.Add(request);using System.Drawing.Image image=System.Drawing.Image.FromFile(path);return Task.FromResult<ExtractedApplicationIcon?>(new(path,image.Width,image.Height,request.Identity,File.GetLastWriteTimeUtc(path)));}}
}
